// ================== CONFIGURE AQUI ==================
const TOKEN = 'TROQUE-POR-UMA-CHAVE-SECRETA'; // a mesma chave das Configurações do copiloto
// ====================================================
const b = $input.first().json.body || {};
if (b.token !== TOKEN) throw new Error('Chave do copiloto inválida');
if (b.evento === 'teste') return [{ json: { teste: true } }];

const conversa = (b.conversa || []).map(m => `${m.quem === 'cliente' ? 'PACIENTE' : 'CLÍNICA'}: ${m.texto}`).join('\n');
const o = b.orcamento || {};

if (b.evento === 'avaliar_consulta') {
  const prompt = `TAREFA: AVALIAR a condução desta consulta (não sugerir fala).
Canal: ${b.canal} · Unidade: ${b.unidade} · Etapa alcançada: ${b.etapa} · Resultado: ${b.resultado || 'não registrado'}
Dor: ${(b.notas && b.notas.dor) || '-'} · Evento: ${(b.notas && b.notas.evento) || '-'}
Orçamento: ${o.tratamento || '-'} · ${o.valor || '-'} · Objeções: ${(b.objecoes || []).join(', ') || 'nenhuma'}
Nota calculada pelo roteiro: ${b.nota_local}/100

CONVERSA:
${conversa || '(sem mensagens)'}

Avalie de 0 a 10: acolhimento, descoberta da dor, uso do iTero/simulação, apresentação da solução, apresentação do investimento, tratamento das objeções, fechamento e próximo passo.
Use o MESMO formato JSON: em "orientacao" coloque "Nota geral X/10 — frase-resumo"; em "mensagem" coloque, em tópicos curtos: notas por critério, 3 pontos fortes, 3 pontos a melhorar (com a frase exata que poderia ter sido dita) e a próxima ação recomendada com esse paciente.`;
  return [{ json: { teste: false, prompt } }];
}
const prompt = `Canal: ${b.canal === 'presencial' ? 'consulta presencial' : 'WhatsApp'} · Unidade: ${b.unidade}
Etapa atual do roteiro: ${b.etapa} — objetivo: ${b.objetivo_etapa}
Paciente: ${(b.paciente && b.paciente.nome) || 'não informado'}
Dor principal: ${(b.notas && b.notas.dor) || '-'} · Evento/prazo: ${(b.notas && b.notas.evento) || '-'}
Notas: ${(b.notas && b.notas.livre) || '-'}
Orçamento: ${o.tratamento || '-'} · valor ${o.valor || '-'} · entrada ${o.entrada || '-'} · parcelas ${o.parcelas || '-'}
Temperatura (0-100): ${b.temperatura} · Objeções já detectadas: ${(b.objecoes || []).join(', ') || 'nenhuma'}

CONVERSA (mais recente por último):
${conversa || '(sem mensagens)'}

Qual a melhor próxima resposta da clínica?`;
return [{ json: { teste: false, prompt } }];

const out = $input.first().json.output || $input.first().json.text || '';
let r = { orientacao: '', mensagem: String(out).trim() };
try {
  const m = String(out).match(/\{[\s\S]*\}/);
  if (m) { const j = JSON.parse(m[0]); r = { orientacao: j.orientacao || '', mensagem: j.mensagem || r.mensagem }; }
} catch (e) { /* resposta fora do formato: devolve o texto puro */ }
return [{ json: { ok: true, sugestao: r.mensagem, orientacao: r.orientacao } }];
